package net.civeira.phylax.feature.oauth.authentication.domain;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import io.quarkus.runtime.annotations.RegisterForReflection;
import lombok.Data;

/**
 * Mutable authentication context used during token issuance.
 *
 * Responsibilities: - Hold authenticated user identity and claims. - Track audiences, scopes, and
 * roles for tokens.
 *
 * Design notes: - Mutable to allow incremental enrichment during flows. - Used by token builders
 * and session stores.
 */
@Data
@RegisterForReflection
public class AuthenticationData {
  /**
   * Unique identifier for the authenticated subject.
   */
  private String uid;
  /**
   * Authenticated username or subject name. Used to resolve user data during token creation.
   */
  private String username;
  /**
   * Roles granted to the user, keyed by audience.
   */
  private Map<String, List<String>> roles = new LinkedHashMap<>();
  /**
   * Roles granted to the user, keyed by audience.
   */
  private Map<String, List<String>> groups = new LinkedHashMap<>();
  /**
   * Audiences requested for the token. Used to scope roles and access claims.
   */
  private List<String> audiences = new ArrayList<>();
  /**
   * Audiences of the whole grant, kept by its refresh tokens when an access token is narrowed to
   * some resources (RFC 8707, task 4.7). Null when they are the access token ones.
   */
  private List<String> grantAudiences;
  /**
   * Scopes granted to the access token. Used by resource servers for authorization.
   */
  private List<String> scopes = new ArrayList<>();

  /**
   * Tenant identifier for the current authentication context.
   */
  private String tenant;

  /**
   * Authentication mode used for this session.
   */
  private AuthenticationMode mode;

  /**
   * When the user actually authenticated (OIDC {@code auth_time}). A code exchange or a refresh
   * keeps the one of the original login (task 1.13).
   */
  private Instant time;

  /**
   * Authentication methods the user actually used (RFC 8176 values: {@code pwd}, {@code otp},
   * {@code mfa}), carried from the login to every token of the grant (task 1.13).
   */
  private List<String> amr = new ArrayList<>();

  /**
   * Public identifier of the SSO session (OIDC {@code sid}): random, stable while the session lives
   * and distinct from the session cookie (tasks 1.2 and 1.14). Null outside a session.
   */
  private String sid;

  /**
   * Adds role names for the given audience.
   *
   * Roles are prefixed with the audience when not a wildcard. The resulting list is appended to the
   * current roles.
   *
   * @param audience audience name or wildcard
   * @param names role names to add
   */
  public void addRolesTo(String audience, List<String> names) {
    roles.computeIfAbsent(audience, _ -> new ArrayList<>()).addAll(names);
  }

  public void addGroupsTo(String audience, List<String> names) {
    groups.computeIfAbsent(audience, _ -> new ArrayList<>()).addAll(names);
  }
}
